contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint deposit, uint minSum, uint am) public payable {
        require(deposit < type(uint128).max);
        require(am < type(uint128).max);
        c.SetMinSum(minSum);
        c.Deposit{value: deposit}();
        uint balBefore = c.balances(address(this));
        bool reverted;
        try c.Collect(am) { reverted = false; }
        catch { reverted = true; }
        uint balAfter = c.balances(address(this));
        if (balBefore >= minSum && balBefore >= am) {
            assert(!reverted && balAfter == balBefore - am);
        } else {
            assert(reverted && balAfter == balBefore);
        }
    }
    receive() external payable {}
}

